body:
Full Authentication Flow:
Please set up config file first, refer to example_config file

API:
// sign up for an account
(POST) localhost:3000/signup
{
    "first_name": "Jeff",
    "last_name": "Lee",
    "Password": "password1",
    "email": "clee051@e.ntu.edu.sg",
    "user_type" : "USER"
}
Expected Returns:
{
    "Success": "Successful Sign Up"
}

// get the verification code from email
// verify with verification code
(POST) localhost:3000/verify
{
    "email": "clee051@e.ntu.edu.sg",
    "verification_key": "838291"
}
Expected Returns:
{
    "Success": "Verified"
}

// login to get the access token
(POST) localhost:3000/login
{
    "first_name": "Jeff",
    "last_name": "Lee",
    "Password": "password1",
    "email": "clee051@e.ntu.edu.sg",
    "user_type" : "USER"
}
Expected Returns:
{
    "first_name": "Jeff",
    "last_name": "Lee",
    "Password": "$2a$14$OBpe.WjBrAXut1UmBoZfSucSokfIaWZ3Y6Noxo4dcE/UkHma5i2AK",
    "email": "clee051@e.ntu.edu.sg",
    "token": "ACCESS_TOKEN",
    "user_type": "USER",
    "refresh_token": "REFRESH_TOKEN",
    "verification_key": "838291",
    "created_at": "2021-05-16T16:19:32+08:00",
    "updated_at": "2021-05-16T16:19:32+08:00"
}

// use the access token to access authorized pages
(GET) localhost:3000/home/
Authorization Header "bear: ACCESS_TOKEN"
Expected Returns:
{
    "Success": "Successful Entry"
}
